// CALIPER Tier-Based Procedural Asset Library (2,400 Models)
// 10 Categories x 6 Quality Tiers x 40 Models each
import * as THREE from 'three';

export function normalizeGeometry(geom) {
  if (!geom || !geom.attributes || !geom.attributes.position) return geom;
  geom.computeBoundingBox();
  const b = geom.boundingBox;
  const cx = (b.max.x + b.min.x) / 2;
  const cz = (b.max.z + b.min.z) / 2;
  const shiftY = b.min.y < 0 ? -b.min.y : (b.min.y > 0.001 ? -b.min.y : 0);
  geom.translate(-cx, shiftY, -cz);
  geom.computeBoundingBox();
  return geom;
}

export function tagGeometry(geom, r = 0.6, g = 0.6, b = 0.6, T = THREE) {
  if (!geom || !geom.attributes || !geom.attributes.position) return geom;
  if (!geom.attributes.color) {
    const count = geom.attributes.position.count;
    const colors = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      colors[i * 3] = r;
      colors[i * 3 + 1] = g;
      colors[i * 3 + 2] = b;
    }
    geom.setAttribute('color', new T.BufferAttribute(colors, 3));
  }
  return geom;
}

export function mergeGeometries(geoms, T = THREE) {
  const clean = (geoms || []).filter(g => g && g.attributes && g.attributes.position);
  if (clean.length === 0) return new T.BufferGeometry();
  if (clean.length === 1) return normalizeGeometry(clean[0].clone ? clean[0].clone() : clean[0]);

  let totalPos = 0;
  let totalIdx = 0;
  for (const g of clean) {
    totalPos += g.attributes.position.count;
    totalIdx += g.index ? g.index.count : g.attributes.position.count;
  }

  const positions = new Float32Array(totalPos * 3);
  const normals = new Float32Array(totalPos * 3);
  const colors = new Float32Array(totalPos * 3);
  const uvs = new Float32Array(totalPos * 2);
  const indices = new (totalPos > 65535 ? Uint32Array : Uint16Array)(totalIdx);

  let pOffset = 0;
  let iOffset = 0;
  let vOffset = 0;

  for (const g of clean) {
    const pos = g.attributes.position;
    const norm = g.attributes.normal;
    const col = g.attributes.color;
    const uv = g.attributes.uv;

    positions.set(pos.array, pOffset * 3);
    if (norm) {
      normals.set(norm.array, pOffset * 3);
    }
    if (col) {
      colors.set(col.array, pOffset * 3);
    } else {
      for (let i = 0; i < pos.count; i++) {
        colors[(pOffset + i) * 3] = 0.65;
        colors[(pOffset + i) * 3 + 1] = 0.65;
        colors[(pOffset + i) * 3 + 2] = 0.65;
      }
    }
    if (uv) {
      uvs.set(uv.array, pOffset * 2);
    } else {
      for (let i = 0; i < pos.count; i++) {
        uvs[(pOffset + i) * 2] = 0.97;
        uvs[(pOffset + i) * 2 + 1] = 0.97;
      }
    }

    if (g.index) {
      for (let i = 0; i < g.index.count; i++) {
        indices[iOffset++] = g.index.array[i] + vOffset;
      }
    } else {
      for (let i = 0; i < pos.count; i++) {
        indices[iOffset++] = i + vOffset;
      }
    }
    pOffset += pos.count;
    vOffset += pos.count;
  }

  const merged = new T.BufferGeometry();
  merged.setAttribute('position', new T.BufferAttribute(positions, 3));
  merged.setAttribute('normal', new T.BufferAttribute(normals, 3));
  merged.setAttribute('color', new T.BufferAttribute(colors, 3));
  merged.setAttribute('uv', new T.BufferAttribute(uvs, 2));
  merged.setIndex(new T.BufferAttribute(indices, 1));
  return normalizeGeometry(merged);
}


