// bld-f1-alpine-chalet
export function bld_f1_alpine_chalet() {
  return {
    id: 'bld-f1-alpine-chalet',
    name: "Basic: Alpine Chalet",
    tier: 'midlow',
    finish: 'f1',
    category: 'buildings',
    footprint: { w: 15.20, d: 15.20, h: 16.00 },
    lod: [
      {
        level: 0,
        tris: 250,
        createGeometry: (T = THREE) => {
          const geoms = [];
          const w = 15.20, d = 15.20, h = 16.00;

          
          // Standard block / bar massing
          const main = new T.BoxGeometry(w, h, d);
          main.translate(0, h / 2, 0);
          tagGeometry(main, 0.7, 0.68, 0.65, T);
          geoms.push(main);
          

          // Entrance Portal & Canopy
          const portal = new T.BoxGeometry(Math.min(6, w * 0.3), Math.min(4, h * 0.25), 1.2);
          portal.translate(0, Math.min(2, h * 0.125), d / 2 + 0.3);
          tagGeometry(portal, 0.55, 0.45, 0.35, T);
          geoms.push(portal);

          const canopy = new T.BoxGeometry(Math.min(7, w * 0.35), 0.5, 2.5);
          canopy.translate(0, Math.min(4.2, h * 0.27), d / 2 + 0.9);
          tagGeometry(canopy, 0.88, 0.86, 0.82, T);
          geoms.push(canopy);

          

          

          

          

          

          return mergeGeometries(geoms, T);
        }
      },
      {
        level: 1,
        tris: 36,
        createGeometry: (T = THREE) => {
          const w = 15.20, d = 15.20, h = 16.00;
          const b = new T.BoxGeometry(w, h, d);
          b.translate(0, h / 2, 0);
          return normalizeGeometry(tagGeometry(b, 0.7, 0.68, 0.65, T));
        }
      },
      {
        level: 2,
        tris: 12,
        createGeometry: (T = THREE) => {
          const w = 15.20, d = 15.20, h = 16.00;
          const b = new T.BoxGeometry(w, h, d);
          b.translate(0, h / 2, 0);
          return tagGeometry(b, 0.55, 0.57, 0.60, T);
        }
      }
    ]
  };
}

// bld-f2-alpine-chalet
export function bld_f2_alpine_chalet() {
  return {
    id: 'bld-f2-alpine-chalet',
    name: "Standard: Alpine Chalet",
    tier: 'mid',
    finish: 'f2',
    category: 'buildings',
    footprint: { w: 15.20, d: 15.20, h: 16.00 },
    lod: [
      {
        level: 0,
        tris: 400,
        createGeometry: (T = THREE) => {
          const geoms = [];
          const w = 15.20, d = 15.20, h = 16.00;

          
          // Standard block / bar massing
          const main = new T.BoxGeometry(w, h, d);
          main.translate(0, h / 2, 0);
          tagGeometry(main, 0.75, 0.72, 0.68, T);
          geoms.push(main);
          

          // Entrance Portal & Canopy
          const portal = new T.BoxGeometry(Math.min(6, w * 0.3), Math.min(4, h * 0.25), 1.2);
          portal.translate(0, Math.min(2, h * 0.125), d / 2 + 0.3);
          tagGeometry(portal, 0.6, 0.48, 0.36, T);
          geoms.push(portal);

          const canopy = new T.BoxGeometry(Math.min(7, w * 0.35), 0.5, 2.5);
          canopy.translate(0, Math.min(4.2, h * 0.27), d / 2 + 0.9);
          tagGeometry(canopy, 0.88, 0.86, 0.82, T);
          geoms.push(canopy);

          
          // Roof Cornice Trim
          const cornice = new T.BoxGeometry(w * 1.02, 0.8, d * 1.02);
          cornice.translate(0, h - 0.4, 0);
          tagGeometry(cornice, 0.88, 0.86, 0.82, T);
          geoms.push(cornice);
          

          
          // Facade Pilasters
          const pilasterCount = Math.max(2, Math.floor(w / 6));
          const stepX = (w * 0.85) / pilasterCount;
          for (let i = 0; i <= pilasterCount; i++) {
            const px = -w * 0.425 + i * stepX;
            const pilaster = new T.BoxGeometry(0.8, h * 0.88, 0.4);
            pilaster.translate(px, h * 0.48, d / 2 + 0.15);
            tagGeometry(pilaster, 0.88, 0.86, 0.82, T);
            geoms.push(pilaster);
          }
          

          
          // Balconies
          const floors = Math.max(2, Math.floor(h / 4));
          for (let f = 1; f < floors; f++) {
            const by = f * 4;
            const balc = new T.BoxGeometry(Math.min(5, w * 0.3), 1.0, 1.6);
            balc.translate(0, by, d / 2 + 0.7);
            tagGeometry(balc, 0.6, 0.48, 0.36, T);
            geoms.push(balc);
          }
          

          

          

          return mergeGeometries(geoms, T);
        }
      },
      {
        level: 1,
        tris: 36,
        createGeometry: (T = THREE) => {
          const w = 15.20, d = 15.20, h = 16.00;
          const b = new T.BoxGeometry(w, h, d);
          b.translate(0, h / 2, 0);
          return normalizeGeometry(tagGeometry(b, 0.75, 0.72, 0.68, T));
        }
      },
      {
        level: 2,
        tris: 12,
        createGeometry: (T = THREE) => {
          const w = 15.20, d = 15.20, h = 16.00;
          const b = new T.BoxGeometry(w, h, d);
          b.translate(0, h / 2, 0);
          return tagGeometry(b, 0.55, 0.57, 0.60, T);
        }
      }
    ]
  };
}

