export function bld_f3_art_deco_skyscraper() {
  return {
    id: 'bld-f3-art-deco-skyscraper',
    name: "Premium: Art Deco Skyscraper",
    tier: 'highend',
    finish: 'f3',
    category: 'buildings',
    footprint: { w: 38.00, d: 38.00, h: 136.00 },
    lod: [
      {
        level: 0,
        tris: 550,
        createGeometry: (T = THREE) => {
          const geoms = [];
          const w = 38.00, d = 38.00, h = 136.00;

          
          // Tower on podium
          const podH = Math.min(12, h * 0.25);
          const pod = new T.BoxGeometry(w, podH, d);
          pod.translate(0, podH / 2, 0);
          tagGeometry(pod, 0.68, 0.52, 0.38, T);
          geoms.push(pod);

          const towerW = w * 0.75, towerD = d * 0.75, towerH = h - podH;
          const tower = new T.BoxGeometry(towerW, towerH, towerD);
          tower.translate(0, podH + towerH / 2, 0);
          tagGeometry(tower, 0.8, 0.78, 0.74, T);
          geoms.push(tower);
          

          // Entrance Portal & Canopy
          const portal = new T.BoxGeometry(Math.min(6, w * 0.3), Math.min(4, h * 0.25), 1.2);
          portal.translate(0, Math.min(2, h * 0.125), d / 2 + 0.3);
          tagGeometry(portal, 0.68, 0.52, 0.38, T);
          geoms.push(portal);

          const canopy = new T.BoxGeometry(Math.min(7, w * 0.35), 0.5, 2.5);
          canopy.translate(0, Math.min(4.2, h * 0.27), d / 2 + 0.9);
          tagGeometry(canopy, 0.88, 0.86, 0.82, T);
          geoms.push(canopy);

          
          // Roof Cornice Trim
          const cornice = new T.BoxGeometry(w * 1.02, 0.8, d * 1.02);
          cornice.translate(0, h - 0.4, 0);
          tagGeometry(cornice, 0.88, 0.86, 0.82, T);
          geoms.push(cornice);
          

          
          // Facade Pilasters
          const pilasterCount = Math.max(2, Math.floor(w / 6));
          const stepX = (w * 0.85) / pilasterCount;
          for (let i = 0; i <= pilasterCount; i++) {
            const px = -w * 0.425 + i * stepX;
            const pilaster = new T.BoxGeometry(0.8, h * 0.88, 0.4);
            pilaster.translate(px, h * 0.48, d / 2 + 0.15);
            tagGeometry(pilaster, 0.88, 0.86, 0.82, T);
            geoms.push(pilaster);
          }
          

          
          // Balconies
          const floors = Math.max(2, Math.floor(h / 4));
          for (let f = 1; f < floors; f++) {
            const by = f * 4;
            const balc = new T.BoxGeometry(Math.min(5, w * 0.3), 1.0, 1.6);
            balc.translate(0, by, d / 2 + 0.7);
            tagGeometry(balc, 0.68, 0.52, 0.38, T);
            geoms.push(balc);
          }
          

          
          // Rooftop Crown / Mechanical / Skylight
          const crown = new T.BoxGeometry(w * 0.5, 2.5, d * 0.5);
          crown.translate(0, h + 1.25, 0);
          tagGeometry(crown, 0.35, 0.38, 0.42, T);
          geoms.push(crown);
          

          

          return mergeGeometries(geoms, T);
        }
      },
      {
        level: 1,
        tris: 36,
        createGeometry: (T = THREE) => {
          const w = 38.00, d = 38.00, h = 136.00;
          const b = new T.BoxGeometry(w, h, d);
          b.translate(0, h / 2, 0);
          return normalizeGeometry(tagGeometry(b, 0.8, 0.78, 0.74, T));
        }
      },
      {
        level: 2,
        tris: 12,
        createGeometry: (T = THREE) => {
          const w = 38.00, d = 38.00, h = 136.00;
          const b = new T.BoxGeometry(w, h, d);
          b.translate(0, h / 2, 0);
          return tagGeometry(b, 0.55, 0.57, 0.60, T);
        }
      }
    ]
  };
}

