          tagGeometry(wallN, 0.85, 0.82, 0.78, T);
          geoms.push(wallN);

          const wallS = new T.BoxGeometry(w, h, d * 0.25);
          wallS.translate(0, h / 2, d * 0.375);
          tagGeometry(wallS, 0.85, 0.82, 0.78, T);
          geoms.push(wallS);

          const wallW = new T.BoxGeometry(w * 0.25, h, d * 0.5);
          wallW.translate(-w * 0.375, h / 2, 0);
          tagGeometry(wallW, 0.85, 0.82, 0.78, T);
